    try:
        if cast is bool:
            return val.strip().lower() in ("true", "1", "yes", "on", "y")
        return cast(val)
    except (ValueError, TypeError):
        logger.warning(f"环境变量 {key}='{val}' 无法转换为 {
                       cast.__name__}，已回退至默认值: {default}")
        return default


