def _extract_tail_json(text: str) -> str | None:
    """
    从含纯文本思考过程的响应中提取尾部 JSON。
    使用锚点跳跃 + 引号状态机，避免 O(n) 盲扫和字符串内花括号误判。
    """
    if not text:
        return None

    # 1. 锚点定位：直接跳到最后一个 }，跳过整个思考过程的无效遍历
    search_end = len(text)
    while True:
        json_end = text.rfind('}', 0, search_end)
        if json_end == -1:
            return None

        # 2. 从锚点向前搜索匹配的 {，带引号状态感知
        brace_depth = 0
        in_string = False
        escape_next = False
        json_start = -1

        for i in range(json_end, -1, -1):
            ch = text[i]

            # 转义字符处理：\" 不应切换引号状态
            if escape_next:
                escape_next = False
                continue
            if ch == '\\' and in_string:
                escape_next = True
                continue

