_EDGE_DASH_MAP = EDGE_DASH_MAP


def get_edge_style(edge_type: str) -> dict[str, Any]:
    """
    根据边类型返回 pyvis add_edge 可用的样式字典。

    Parameters
    ----------
    edge_type : str
        边类型，应为 EDGE_TYPE_HARD / SOFT / CONDITIONAL / RETRY 之一。

    Returns
    -------
    dict
        包含 color, width, dashes 等键，可直接 **kwargs 传给 net.add_edge()。
    """
    # 取字典中第一个值作为 fallback（通常是 hard）
    _default_color = next(iter(EDGE_TYPE_COLOR.values()), "#666666")
    _default_style = next(iter(EDGE_TYPE_STYLE.values()), "solid")

    color = EDGE_TYPE_COLOR.get(edge_type, _default_color)
    style = EDGE_TYPE_STYLE.get(edge_type, _default_style)

    width = (
        RENDER_EDGE_WIDTH * 0.75
        if edge_type == "soft"          # ← 字符串字面量，无需导入常量
        else RENDER_EDGE_WIDTH
    )

    if style == "solid":
        dashes: Any = False
    else:
        dashes = _EDGE_DASH_MAP.get(style, [10, 5])

    return {
        "color": color,
        "width": width,
        "dashes": dashes,
    }

