def _get_details(node: dict[str, Any]) -> str:
    """
    从节点数据中提取详情描述文本。
    优先取 meta.details，其次取 description，最后返回空字符串。
    """
    meta: dict[str, Any] = node.get("meta", {}) or {}
    details = meta.get("details") or node.get("description") or ""
    return str(details).strip()


